package com.example.demo.controller;
import com.example.demo.repository.RoleRepository;import com.example.demo.service.UserService;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller @RequestMapping("/admin/users") public class AdminUserController {private final UserService users;private final RoleRepository roles;public AdminUserController(UserService u,RoleRepository r){users=u;roles=r;}@GetMapping String list(@RequestParam(required=false)String q,Model m){m.addAttribute("users",users.search(q));m.addAttribute("roles",roles.findAll());m.addAttribute("q",q);return "admin/users";}@PostMapping("/{id}/role")String role(@PathVariable Long id,@RequestParam Long roleId,RedirectAttributes ra){users.changeRole(id,roleId);ra.addFlashAttribute("success","Роль изменена");return "redirect:/admin/users";}}
